    selected: resolved ? best : null,
    top_candidates: candidates.slice(0, 10)
  }
} }];

const job = $('Get Website Verification Job').first().json || {};
const rows = $input.all().map((item) => item.json || {});
const lookupFailed = rows.some((row) => row.error || row.errorCode || row.errorMessage);
const activeIntakeStatuses = new Set([
  'awaiting_website_verification',
  'website_verification_pending',
  'website_verification_processing',
  'website_verification_retry_pending'
]);
const activeVerificationStatuses = new Set([
  'pending',
  'resolving',
  'search_running',
  'search_polling',
  'probe_pending',
  'probe_processing'
]);
const verifiedCount = rows.filter((row) => String(row.website_verification_status || '').trim().toLowerCase() === 'verified').length;
const manualReviewCount = rows.filter((row) => String(row.intake_status || '').trim().toLowerCase() === 'manual_review_required').length;
const activeRows = rows.filter((row) =>
  row.id
  && row.job_id === job.job_id
  && (
    activeIntakeStatuses.has(String(row.intake_status || '').trim().toLowerCase())
    || activeVerificationStatuses.has(String(row.website_verification_status || '').trim().toLowerCase())
  )
);
return [{ json: {
  ...job,
  verified_candidate_count: verifiedCount,
  manual_review_candidate_count: manualReviewCount,
  remaining_candidate_found: activeRows.length > 0,
  remaining_candidate_count: activeRows.length,
  completion_lookup_failed: lookupFailed,
  ready_for_handoff: Boolean(job.job_id && !lookupFailed && activeRows.length === 0)
} }];

const row = $json || {};
return [{ json: {
  job_id: row.job_id,
  event_type: 'website_verification_completed',
  event_status: 'queued',
  event_stage: 'lead_intake_queued',
  event_severity: 'info',
  event_error_code: '',
  event_message: 'Website verification finished; lead intake and data cleaning queued.',
  event_payload: { progress_percent: 40, next_workflow: '01 - Lead Intake & Data Cleaning' }
} }];

const cutoff = Date.now() - 10 * 60 * 1000;
const recoverable = new Set(['resolving', 'search_polling', 'probe_processing']);
return $input.all().filter((item) => {
  const row = item.json || {};
  const status = String(row.website_verification_status || '').toLowerCase();
  const timestamp = Date.parse(row.website_verification_locked_at || row.updated_at || '');
  return row.id && recoverable.has(status) && Number.isFinite(timestamp) && timestamp < cutoff;
}).map((item) => {
  const row = item.json || {};
  const before = String(row.website_verification_status || '').toLowerCase();
  const verificationNext = before === 'search_polling' ? 'search_running' : (before === 'probe_processing' ? 'probe_pending' : 'pending');
  const intakeNext = before === 'resolving' ? 'website_verification_retry_pending' : 'website_verification_processing';
  return { json: { ...row, stale_verification_status: before, stale_verification_worker_id: row.website_verification_locked_by, verification_recovery_status: verificationNext, intake_recovery_status: intakeNext } };
});
